    "note_pins_label": "Macho vs Fêmea",
    "note_pins": "Conectores machos possuem pinos guia; conectores fêmeas possuem furos para os pinos guia. Transceivers usam MPO fêmea; cabos de manobra (patch cables) são tipicamente macho-fêmea.",
