    "strat_cubic": "Função cúbica — agressiva em redes de alto BDP",
    "strat_bbr": "Baseado em modelo — estima largura de banda e RTT",
    "loss_resp_reno": "cwnd reduzido para metade em caso de perda; o timeout repõe para 1 MSS",
