    "phase_slow_start": "Slow Start",
    "phase_ca": "Congestion Avoidance",
    "phase_fast_recovery": "Fast Recovery",
    "sysctl_title": "Ajuste de TCP no Linux (sysctl)",
    "sysctl_subtitle": "Gere comandos sysctl para ajustar os buffers de TCP e o controlo de congestão do Linux para os parâmetros do seu caminho.",
    "sysctl_algo": "Algoritmo de Controlo de Congestão",
    "sysctl_apply_hint": "Aplicar com: sysctl -p /etc/sysctl.d/99-tcp-tuning.conf. Os valores são calculados a partir do seu BDP.",
    "ref_title": "Referência de Algoritmo",
    "ref_reno_desc": "Algoritmo AIMD clássico. O slow start duplica o cwnd a cada RTT até ao ssthresh. O congestion avoidance adiciona ~1 segmento por RTT. Com 3 ACKs duplicados: ssthresh = cwnd/2, cwnd = ssthresh. No timeout: cwnd = 1 MSS. Justo, mas subutiliza caminhos de alto BDP após perda.",
    "ref_cubic_desc": "Padrão no Linux. Utiliza uma função cúbica W(t) = C(t-K)^3 + W_max (C=0,4, beta=0,7). Após perda, o cwnd cai para 70% de W_max, crescendo depois através della curva côncavo-convexa. Mais agressivo do que o Reno em long-fat networks. K = (W_max * 0,3 / C)^(1/3).",
    "ref_bbr_desc": "Algoritmo baseado em modelo da Google. Estima a largura de banda do gargalo e o RTT mínimo em vez de usar a perda como sinal. Fases: Startup (ganho 2,89x), Drain, ProbeBW (ciclo de ganho de 8 fases: 1,25/0,75/1...), ProbeRTT (4 segmenti a cada ~10s). Obtém o throughput total mesmo com perdas.",
