    "plat_iosxe_notes": "Certifique-se de que o sistema de ficheiros flash tem espaço livre suficiente com \"show flash:\". Se utilizar SCP, é necessário configurar \"ip scp server enable\" no servidor, ou o dispositivo deve ter o encaminhamento SSH ativado.",
    "plat_iosxr_notes": "Os sistemas de ficheiros do IOS-XR usam disk0: ou disk1: em vez de flash:. Os comandos SCP/SFTP no XR pedem a palavra-passe do utilizador de forma interativa. O contexto de encaminhamento (VRF) pode ser configurado globalmente.",
    "plat_nxos_notes": "O NX-OS usa bootflash: por predefinição. Verifique o espaço do sistema de ficheiros com \"dir bootflash:\". O VRF deve ter acessibilidade IP ao servidor; verifique o encaminhamento predefinido ou o VRF de gestão.",
    "plat_junos_notes": "As cópias de ficheiros no Junos são colocadas em /var/tmp/ ou /var/db/config/. Use \"show system storage\" para verificar o espaço em disco. As transferências TFTP podem exigir configurações do protocolo de encaminhamento do Junos ou a utilização da palavra-chave routing-instance.",
    "plat_eos_notes": "Os dispositivos Arista usam flash:. Verifique com \"dir flash:\". Para elevado débito, a Arista suporta cópias HTTP/HTTPS nativas altamente otimizadas.",
    "plat_fortios_notes": "A restauração TFTP do FortiOS substitui a imagem de arranque e reinicia o dispositivo automaticamente. Utilize com cautela. Guarde sempre os ficheiros de configuração previamente.",
    "plat_panos_notes": "O Palo Alto PAN-OS exige permissões explícitas de administrador CLI para executar comandos de importação de software. O software também pode ser transferido diretamente das atualizações oficiais de suporte da Palo Alto.",
    "plat_linux_notes": "Verifique as permissões de leitura/escrita do diretório de destino. Certifique-se de que o cliente (scp, curl) está instalado. As transferências HTTP/HTTPS via curl/wget são altamente paralelizáveis.",
    "plat_f5_notes": "Verifique os processos bigstart e as permissões de rotas administrativas do F5. A pasta de destino /shared/images/ é a localização predefinida dos ficheiros ISO do F5.",
    "cmd_iosxe": "! Comando Cisco IOS/IOS-XE",
