    "double_nat_title": "NAT Duplo em implementações CGNAT",
    "double_nat_body": "In einer typischen CGNAT-Bereitstellung führen Teilnehmer auch NAT auf ihrem CPE durch – sie übersetzen {rfc1918}-Adressen in ihre zugewiesene 100.64.0.0/10-Adresse, bevor der Datenverkehr überhaupt das Carrier-NAT erreicht. Dieses Doppel-NAT macht UPnP und automatisches Port-Mapping funktionsunfähig, erschwert die manuelle Port-Weiterleitung und ist ein bekannter Schwachpunkt für Gaming, VoIP und alle Anwendungen, die eingehende Verbindungen erfordern.",
