    "desc_strategy_deterministic": "O CGNAT aloca antecipadamente um bloco fixo e reservado de portas de origem a cada subscritor. Isto garante a disponibilidade de portas e reduz a sobrecarga de syslog em 99% (apenas a alocação do bloco é registada, não as sessões individuais), mas limita o total de subscritores por IP público.",
