    "scenario_label": "Selecionar cenário de NAT duplo",
    "scenario_overlap_title": "Cenário 1: Sub-redes Sobrepostas (VPN IPsec)",
    "scenario_overlap_desc": "Duas redes utilizam o mesmo intervalo privado (ex., 192.168.1.0/24). Para comunicar sem conflitos de IP, ambos os lados devem executar NAT. O Host A traduz para um IP de trânsito e o Host B traduz para um IP de trânsito.",
    "scenario_cgnat_title": "Cenário 2: NAT de Nível de Operador (CGNAT) para NAT do Cliente",
    "scenario_cgnat_desc": "O Fornecedor de Serviços aloca 100.64.0.0/10 (RFC 6598) ao WAN do Cliente. O Cliente executa NAT local (192.168.1.0/24 -> 100.64.1.2) e o Fornecedor executa CGNAT (100.64.1.2 -> IP Público) para conservar espaço IPv4.",
