    "err_invalid_ip": "Formato de endereço IP inválido",
    "explanation_title": "Compreender NAT vs. PAT",
    "explanation_intro": "Network Address Translation (NAT) e Port Address Translation (PAT) são técnicas para mapear um espaço de endereços IP noutro, utilizadas principalmente para preservar endereços IPv4 públicos limitados ou resolver conflitos de sub-rede.",
    "nat_expl_title": "1. O que é NAT?",
    "nat_expl_desc": "O NAT traduz endereços IP numa base 1 para 1. Pode ser Estático (mapeamento permanente de um IP privado para um IP público, ideal para servidores virados para o exterior) ou Dinâmico (aloca um IP público de um pool a um host privado sob procura. Assim que todos os IPs públicos forem atribuídos, os hosts subsequentes são bloqueados até que um IP seja libertado). Os números de porta não são modificados.",
    "pat_expl_title": "2. O que é PAT (NAT Overload)?",
    "pat_expl_desc": "O PAT (ou Port Address Translation / NAT Overload) traduz tanto o endereço IP como o número de porta de origem numa base muitos para um (N para 1). Múltiplos hosts privados partilham um único endereço IP público ao atribuir portas de origem únicas (ex. 192.168.1.10:5000 e 192.168.1.11:5000 mapeiam para 203.0.113.10:1024 e 203.0.113.10:1025). Este é o método padrão para routers domésticos e acesso à Internet empresarial.",
    "comparison_table_title": "Resumo Comparativo",
    "comp_header_feature": "Funcionalidade",
    "comp_header_nat": "NAT (1 para 1)",
    "comp_header_pat": "PAT (N para 1 / Overload)",
