    "about_body": "iperf é uma ferramenta de medição ativa para a largura de banda máxima alcançável em redes IP. Um host atua como servidor (ouvinte) e outro se conecta como cliente para enviar (ou receber) tráfego via TCP, UDP ou SCTP, relatando taxa de transferência, jitter e perda de pacotes. iperf3 (binário iperf3) é uma reescrita moderna com saída JSON e modos reverso/bidirecional; iperf2 (binário iperf) é multi-cliente e mais robusto para Wi-Fi e multicast. Os dois NÃO são compatíveis entre si — ambas as pontas devem rodar a mesma versão.",
